#!/usr/bin/perl -i
# Renames ToolExecutionCoordinator::propose to submit, with its approval-era
# wording, in the files given on the command line. Lines that use "propose"
# in an unrelated sense are protected by exact-text checks.
use strict;
use warnings;

while (<>) {
    # Unrelated senses: Orca's orientation proposals and the banned-word list
    # in the printer note check.
    if (/as Orca proposes/ || /"Propose", "propose"/) { print; next; }

    # Phrases that need wording, not just a word swap.
    s/before proposal execution/before a submitted call runs/g;
    s/refused at proposal/refused at submission/g;
    s/Refused at proposal/Refused at submission/g;
    s/-> proposes duplicating an object that/-> submits a call to duplicate an object that/;
    s/-> proposes the duplicate with a long/-> submits the duplicate with a long/;
    s/-> proposes duplicating the selected/-> submits a call to duplicate the selected/;
    s/\bproposalConversation\b/toolCallConversation/g;

    # Identifiers and plain word forms.
    s/\bpropose_/submit_/g;
    s/_propose\b/_submit/g;
    s/\bproposed\b/submitted/g;
    s/\bProposed\b/Submitted/g;
    s/\bproposes\b/submits/g;
    s/\bpropose\b/submit/g;
    print;
}

